# Get non-empty, non-comment lines
lines = [line.strip() for line in student_code.split('\n') if line.strip() and not line.strip().startswith('#')]

# Task 1: Check import
if not any('from bs4 import BeautifulSoup' in line for line in lines):
    raise AssertionError('Task 1: Missing "from bs4 import BeautifulSoup"')

# Task 2: Check BeautifulSoup() call
if not any('soup' in line and 'BeautifulSoup' in line and 'html.parser' in line for line in lines):
    raise AssertionError("Task 2: soup should use BeautifulSoup() with 'html.parser'")
if not any('html_doc' in line and 'html.parser' in line for line in lines):
    raise AssertionError("Task 2: Should pass html_doc and 'html.parser' to BeautifulSoup()")

# Task 3: Check .find_all('a')
if not any(".find_all('a')" in line or '.find_all("a")' in line for line in lines):
    raise AssertionError("Task 3: Should use soup.find_all('a')")

# Task 4: Check href extraction with loop
if 'for link in all_links:' not in student_code:
    raise AssertionError('Task 4: Should loop through all_links')
if not any("link['href']" in line or 'link["href"]' in line for line in lines):
    raise AssertionError("Task 4: Should access href with link['href']")
if not any('print' in line and 'href' in line for line in lines):
    raise AssertionError('Task 4: Should print each href')

# Task 5: Check find and .text
if not any(".find('p')" in line or '.find("p")' in line for line in lines):
    raise AssertionError("Task 5: Should use soup.find('p')")
if not any('paragraph' in line and '.text' in line and 'print' in line for line in lines):
    raise AssertionError('Task 5: Should print paragraph.text')

print('TEST_PASSED')
